<script>
(function(){const tabs=[...document.querySelectorAll('[data-profile-tab]')];const panels=[...document.querySelectorAll('[data-profile-panel]')];function activate(name){tabs.forEach(tab=>{const selected=tab.dataset.profileTab===name;tab.classList.toggle('active',selected);tab.setAttribute('aria-selected',String(selected));});panels.forEach(panel=>panel.hidden=panel.dataset.profilePanel!==name);}tabs.forEach(tab=>tab.addEventListener('click',()=>activate(tab.dataset.profileTab)));@if($errors->has('current_password') || $errors->has('password'))activate('password');@endif})();
</script>
